function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fill("#85c57a", 45); // Golden hour light
  brush.fill("#77ccaa", 20); // Amber-leaning sky
  brush.fill("#99ffe6", 60); // Soft lavender
  brush.fill("#8dd3ff", 20); // Pastel blue
  brush.fill("#80c0a0", 40); // Warm cream

  // Hills
  brush.fill("#5c6b4d", 40); // Dark green
  brush.fill("#7e8f5c", 35); // Medium green
  brush.fill("#a1b37e", 30); // Light green
  brush.fill("#c4d9a0", 10); // Pale green
  brush.fill("#f5f9d0", 15); // Verdant green

  // Mountains
  brush.fill("#85c57a", 60); // Pale yellow
  brush.fill("#a9c188", 40); // Orange
  brush.fill("#d3d493", 20); // Gold
  brush.fill("#ffeb9d", 15); // Earth yellow
  brush.fill("#d3d493", 10); // Grayish yellow
  brush.fill("#7d907a", 35); // Halfway shade

  brush.beginShape(curvature);
  brush.vertex(0, 0); // Top of the western hill
  brush.vertex(200, 35); // Base of the western hill
  brush.vertex(240, 75); // Top of the eastern hill
  brush.vertex(400, 60); // Base of the eastern hill
  brush.vertex(360, 95); // Top of the eastern hill
  brush.vertex(400, 125); // Base of the eastern hill
  brush.endShape(true);

  // Horizon
  brush.fill("#d3e9d0", 10); // Warm tan
  brush.fill("#82a390", 20); // Darker tan
  brush.fill("#b9c6b8", 35); // Pale tan
  brush.fill("#d8e0da", 15); // Very pale tan
  brush.fill("#f0e6d5", 40); // Light brown

  brush.noFill();
}
