function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#b2def5", 0.5); // Sky
  brush.fill("#8fa9c9", 0.3); // West horizon
  brush.fill("#4b6d90", 0.8); // Eastern hills

  brush.fill("#52a6a1", 1); // Golden light
  brush.fillBleed(0.75); // Spread toward the horizon
  brush.beginShape(curvature);
  brush.vertex(100, 150); // Top of left hill
  brush.vertex(150, 130); // Top of right hill
  brush.vertex(170, 180); // Bottom of hill
  brush.vertex(200, 180); // Base of hill
  brush.endShape(true);

  brush.fill("#79a2cd", 0.2); // Horizontal light
  brush.circle(200, 180, 40); // Central sun
  brush.fill("#a2c879", 1); // Sunset colors
  brush.beginShape(curvature);
  brush.vertex(300, 100); // Top of right hill
  brush.vertex(350, 80); // Top of left hill
  brush.vertex(370, 120); // Bottom of hill
  brush.vertex(400, 120); // Base of hill
  brush.endShape(true);

  brush.fill("#c9dbf1", 0.2); // Horizon line
  brush.line(0, 180, 400, 180);
  brush.line(0, 200, 400, 200);
}
