function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#e08a72", 30); // orange hills
  brush.fill("#a9d8be", 60); // sky
  brush.fill("#97c163", 15); // light green hills
  brush.fill("#6a925b", 70); // dense green hills
  brush.fill("#4e7869", 10); // shadowy green hills

  brush.fill("#ffffff", 255); // white clouds
  brush.fillTexture(0.5, true); // clouds
  brush.circle(0, 0, 120); // center of the canvas

  brush.beginShape(curvature);
  brush.vertex(0, -40); // top-left hill
  brush.vertex(200, -40); // top-right hill
  brush.vertex(200, 150); // top of sky
  brush.vertex(0, 150); // top-left hill
  brush.endShape(true);

  brush.beginShape(curvature);
  brush.vertex(40, -30); // top-left hill
  brush.vertex(360, -30); // top-right hill
  brush.vertex(360, 150); // top of sky
  brush.vertex(40, 150); // top-left hill
  brush.endShape(true);

  brush.fill("#3b5998", 50); // purple horizon
  brush.circle(0, 180, 120); // center of the canvas
  brush.circle(200, 180, 120); // center of the hills

  brush.fill("#47a088", 60); // green area
  brush.beginShape(curvature);
  brush.vertex(200, 180); // middle of sky
  brush.vertex(200, 180 + 120); // middle of sky
  brush.vertex(220, 180 + 40); // lower middle hill
  brush.vertex(240, 180 + 40); // lower middle hill
  brush.endShape(true);
}
