function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();

  // Sky
  brush.fillBleed(0.3); // Soft background
  brush.fill("#e08a72", 255); // Sun
  brush.fill("#a0d4f3", 255); // Sky
  brush.fill("#99e0e0", 255); // Horizon
  brush.fill("#98c3d5", 255); // Western sky

  // Hills
  brush.fill("#639472", 255); // Light green
  brush.fill("#536c51", 255); // Dark green
  brush.fill("#8c9779", 255); // Medium green
  brush.fill("#5b6f5d", 255); // Darker green
  brush.fillTexture(0.7, border); // Grassy border

  // Ridge
  brush.fill("#c0a186", 255); // Olive
  brush.fill("#808d6d", 255); // Grayish
  brush.beginShape(curvature);
  brush.vertex(120, 180); // Top of hill
  brush.vertex(220, 150); // Middle
  brush.vertex(180, 190); // Bottom
  brush.endShape(true);

  // Shadows
  brush.fill("#5d5d5d", 255); // Dark gray
  brush.beginShape(curvature);
  brush.vertex(120, 220); // Top shadow
  brush.vertex(220, 170); // Middle shadow
  brush.vertex(180, 210); // Bottom shadow
  brush.endShape(true);

  // Foreground
  brush.fill("#c2a187", 255); // Yellow-orange
  brush.beginShape(curvature);
  brush.vertex(240, 220); // Foreground top
  brush.vertex(260, 180); // Foreground middle
  brush.vertex(230, 200); // Foreground bottom
  brush.endShape(true);

  // Few details
  brush.fill("#e08a72", 255); // Sun again
  brush.vertex(260, 180); // Sun position
  brush.vertex(240, 190); // Sun as a small shape
  brush.endShape(true);
}
