function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#e08a72", 100);  // Warm pink at top left
  brush.fill("#b6b0b0", 20);   // Soft gray at top center
  brush.fill("#8d9c86", 50);   // Greyish blue at top right
  brush.circle(0, 0, 50);      // Center of the sky

  // Hills
  brush.fill("#68908a", 100);  // Dark green
  brush.fill("#527b70", 70);   // Medium green
  brush.fill("#36554d", 80);   // Darker green
  brush.fill("#4c6b5f", 20);   // Light green
  brush.beginShape(curvature);
  brush.vertex(0, 50);          // Top left hill
  brush.vertex(200, 150);       // Top right hill
  brush.vertex(400, 150);       // Bottom right hill
  brush.vertex(200, 350);       // Bottom left hill
  brush.endShape(true);

  // Horizon
  brush.fill("#b6b0b0", 50);   // Gray to emphasize the fall
  brush.line(0, 350, 400, 350); // Right side

  // Twilight
  brush.fill("#d6c4a9", 70);   // Warm orange to the right
  brush.fill("#cc755a", 90);   // Crimson at the bottom right
  brush.beginShape(curvature);
  brush.vertex(300, 350);      // Right hill
  brush.vertex(400, 400);      // Bottom right hill
  brush.endShape(true);

  // Stars (optional detail)
  brush.fill("#404040", 20);   // Dark grey stars
  brush.beginShape(curvature);
  for (let i = 0; i < 50; i++) {
    brush.vertex(random(0, 400), random(0, 400));
  }
  brush.endShape(true);
}
